export default function WorkflowDiagram({ workflowInstanceId }) {
  const { useState, useEffect } = React;
  const { Card, Spin, Empty, Tag, Space, Typography } = window.antd;
  const { dataApi } = window.metadata;
  const { Text } = Typography;

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [wf, setWf] = useState(null);
  const [instance, setInstance] = useState(null);
  const [steps, setSteps] = useState([]);
  const [transitions, setTransitions] = useState([]);
  const [executedIds, setExecutedIds] = useState(new Set());

  const fk = (field, value) => ({
    id: 'fk', type: 'group', operator: 'AND',
    children: [{ id: 'c', type: 'condition', field, op: 'equals', value }],
  });

  useEffect(() => {
    let cancelled = false;
    if (!workflowInstanceId) { setLoading(false); setError('No workflow instance linked.'); return; }
    setLoading(true); setError(null);
    (async () => {
      try {
        const inst = await dataApi.getOne('sys_workflow_instance', workflowInstanceId);
        const wfRow = await dataApi.getOne('sys_workflow_definition', inst.workflow_id);
        const [stepsRes, transRes, instRes] = await Promise.all([
          dataApi.list('sys_workflow_step_definition', { filters: fk('workflow_id', inst.workflow_id), pageSize: 500 }),
          dataApi.list('sys_workflow_transition_definition', { filters: fk('workflow_id', inst.workflow_id), pageSize: 500 }),
          dataApi.list('sys_workflow_step_instance', { filters: fk('workflow_instance_id', workflowInstanceId), pageSize: 500 }),
        ]);
        if (cancelled) return;
        setInstance(inst);
        setWf(wfRow);
        setSteps(stepsRes.data || []);
        setTransitions(transRes.data || []);
        setExecutedIds(new Set((instRes.data || []).map((r) => r.step_id)));
      } catch (e) {
        if (!cancelled) setError((e && e.message) || 'Failed to load the workflow diagram.');
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, [workflowInstanceId]);

  if (loading) return <div style={{ padding: 40, textAlign: 'center' }}><Spin /></div>;
  if (error) return <Empty description={error} />;
  if (!steps.length) return <Empty description="This workflow has no steps." />;

  const shapeSize = (t) => (t === 'start' || t === 'end')
    ? { w: 76, h: 76 }
    : (t === 'condition') ? { w: 96, h: 96 } : { w: 140, h: 56 };
  const centerOf = (s) => {
    const size = shapeSize(s.step_type);
    return { x: (s.pos_x || 0) + size.w / 2, y: (s.pos_y || 0) + size.h / 2 };
  };
  const stepById = {};
  steps.forEach((s) => { stepById[s.id] = s; });

  const pad = 60;
  const xs = steps.map((s) => s.pos_x || 0);
  const ys = steps.map((s) => s.pos_y || 0);
  const minX = Math.min.apply(null, xs) - pad;
  const minY = Math.min.apply(null, ys) - pad;
  const maxX = Math.max.apply(null, xs) + pad + 160;
  const maxY = Math.max.apply(null, ys) + pad + 100;
  const width = maxX - minX;
  const height = maxY - minY;

  const EXEC_BG = '#52c41a', EXEC_BORDER = '#389e0d';
  const PENDING_BG = '#f0f0f0', PENDING_BORDER = '#bfbfbf';

  return (
    <Card
      title={'Workflow diagram' + (wf ? ' — ' + (wf.description || wf.name) : '')}
      extra={instance ? (
        <Tag color={instance.status === 'completed' ? 'success' : instance.status === 'failed' ? 'error' : 'processing'}>
          {instance.status}
        </Tag>
      ) : null}
    >
      <Space style={{ marginBottom: 12 }}>
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
          <span style={{ width: 14, height: 14, borderRadius: 3, background: EXEC_BG, border: '1px solid ' + EXEC_BORDER, display: 'inline-block' }} />
          <Text type="secondary" style={{ fontSize: 12 }}>Executed</Text>
        </span>
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, marginLeft: 16 }}>
          <span style={{ width: 14, height: 14, borderRadius: 3, background: PENDING_BG, border: '1px solid ' + PENDING_BORDER, display: 'inline-block' }} />
          <Text type="secondary" style={{ fontSize: 12 }}>Not executed</Text>
        </span>
      </Space>
      <div style={{ overflow: 'auto', border: '1px solid rgba(0,0,0,0.06)', borderRadius: 8 }}>
        <div style={{ position: 'relative', width, height }}>
          <svg width={width} height={height} style={{ position: 'absolute', top: 0, left: 0, pointerEvents: 'none' }}>
            <defs>
              <marker id="wf-diagram-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto">
                <path d="M0,0 L8,4 L0,8 Z" fill="#8c8c8c" />
              </marker>
            </defs>
            {transitions.map((t) => {
              const from = stepById[t.from_step_id];
              const to = stepById[t.to_step_id];
              if (!from || !to) return null;
              let pts = [];
              try { pts = t.points ? JSON.parse(t.points) : []; } catch (e) { pts = []; }
              if (!Array.isArray(pts)) pts = [];
              const c1 = centerOf(from);
              const c2 = centerOf(to);
              const all = [
                { x: c1.x - minX, y: c1.y - minY },
                ...pts.map((p) => ({ x: p.x - minX, y: p.y - minY })),
                { x: c2.x - minX, y: c2.y - minY },
              ];
              const d = 'M ' + all.map((p) => p.x + ',' + p.y).join(' L ');
              return <path key={t.id} d={d} fill="none" stroke="#8c8c8c" strokeWidth={1.5} markerEnd="url(#wf-diagram-arrow)" />;
            })}
          </svg>
          {steps.map((s) => {
            const executed = executedIds.has(s.id);
            const size = shapeSize(s.step_type);
            const left = (s.pos_x || 0) - minX;
            const top = (s.pos_y || 0) - minY;
            const bg = executed ? EXEC_BG : PENDING_BG;
            const border = executed ? EXEC_BORDER : PENDING_BORDER;
            const color = executed ? '#fff' : 'rgba(0,0,0,0.65)';
            const isCircle = s.step_type === 'start' || s.step_type === 'end';
            const isDiamond = s.step_type === 'condition';

            if (isDiamond) {
              return (
                <div key={s.id} style={{ position: 'absolute', left, top, width: size.w, height: size.h }}>
                  <div style={{
                    position: 'absolute', inset: 14, transform: 'rotate(45deg)',
                    border: '2px solid ' + border, background: bg, borderRadius: 4,
                  }} />
                  <div style={{
                    position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center',
                    fontSize: 11, fontWeight: 600, padding: 18, textAlign: 'center', color, overflow: 'hidden',
                  }}>
                    {s.name}
                  </div>
                </div>
              );
            }

            return (
              <div
                key={s.id}
                style={{
                  position: 'absolute', left, top, width: size.w, height: size.h,
                  display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                  textAlign: 'center', fontSize: 11, fontWeight: 600, padding: 6, color,
                  border: '2px solid ' + border, background: bg, boxSizing: 'border-box', overflow: 'hidden',
                  borderRadius: isCircle ? '50%' : 8,
                }}
              >
                <div style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>{s.name}</div>
                {!isCircle && <div style={{ fontSize: 10, fontWeight: 400, opacity: 0.85 }}>{s.step_type}</div>}
              </div>
            );
          })}
        </div>
      </div>
    </Card>
  );
}
